import{_ as a,o as i,c as n,a2 as e}from"./chunks/framework.DtFQgA2F.js";const r=JSON.parse('{"title":"CMake 构建工具","description":"","frontmatter":{"title":"CMake 构建工具"},"headers":[],"relativePath":"notes/01-cpp/build/cmake.md","filePath":"notes/01-cpp/build/cmake.md","lastUpdated":null}'),l={name:"notes/01-cpp/build/cmake.md"};function t(p,s,k,h,d,c){return i(),n("div",null,[...s[0]||(s[0]=[e(`<blockquote><p>CMake 是跨平台构建工具：一份 CMakeLists.txt 描述工程，生成各平台的构建文件，再调用底层工具编译。</p></blockquote><h1 id="markmap-知识体系" tabindex="-1">Markmap 知识体系 <a class="header-anchor" href="#markmap-知识体系" aria-label="Permalink to &quot;Markmap 知识体系&quot;">​</a></h1><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmake</span></span>
<span class="line"><span>├── 官网地址：https://cmake.org/download/</span></span>
<span class="line"><span>├── 工程文件</span></span>
<span class="line"><span>│   ├── CMakeLists.txt 工程描述文件</span></span>
<span class="line"><span>│   │   ├── cmake_minimum_required(VERSION 3.24)  # 最低 CMake 版本</span></span>
<span class="line"><span>│   │   ├── project(ProjectName LANGUAGES CXX)    # 工程名 + C++ 语言</span></span>
<span class="line"><span>│   │   ├── add_executable(ProjectName main.cpp)  # 生成 ProjectName.exe（main.cpp 入口文件）</span></span>
<span class="line"><span>│   └── CMakePresets.json 预设文件</span></span>
<span class="line"><span>├── 构建指令</span></span>
<span class="line"><span>│   ├── cmake -B build          # 配置：生成 build/ 里的构建配置文件</span></span>
<span class="line"><span>│   └── cmake --build build     # 构建：将「代码内容」编译成 .exe 可执行文件</span></span>
<span class="line"><span>├── 构建产物</span></span>
<span class="line"><span>└── END</span></span></code></pre></div><h1 id="faq-常见问题" tabindex="-1">FAQ 常见问题 <a class="header-anchor" href="#faq-常见问题" aria-label="Permalink to &quot;FAQ 常见问题&quot;">​</a></h1><ol><li><p>如何安装 CMake、并检验是否安装成功？</p><details class="details custom-block"><summary>查看答案</summary><p>三种安装方式（任选其一）：</p><ol><li><strong>VS 组件</strong>：Visual Studio Installer →「修改」→ 勾选「适用于 Windows 的 C++ CMake 工具」——随 VS 安装，无需单独配置</li><li><strong>winget</strong>：<code>winget install Kitware.CMake</code>——一条命令装好并自动加入 PATH</li><li><strong>官网</strong>：<a href="https://cmake.org/download/" target="_blank" rel="noreferrer">https://cmake.org/download/</a> → Windows x64 安装包，安装时勾选 Add CMake to PATH</li></ol><p>检验：终端执行</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>输出 <code>cmake version x.y.z</code> 即成功；若提示「不是内部或外部命令」，说明 PATH 没生效，重启终端再试。</p></details></li><li><p>如何 Cmake 构建一个最小的 C++ 程序？</p><details class="details custom-block"><summary>查看答案</summary><p>一个目录放两个文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hello/</span></span>
<span class="line"><span>├── CMakeLists.txt</span></span>
<span class="line"><span>└── main.cpp</span></span></code></pre></div><p><code>main.cpp</code>：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;iostream&gt;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::cout </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Hello CMake&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  std</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::cin.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">get</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 等按一下回车再退出</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>CMakeLists.txt</code>（最小三行）：</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cmake_minimum_required</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">VERSION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 3.24)   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 最低 CMake 版本</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(hello LANGUAGES CXX)           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 工程名 + C++ 语言</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">add_executable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(hello main.cpp)         </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 生成 hello.exe</span></span></code></pre></div><p>然后两步构建：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -B</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # 配置：生成 build/ 里的构建文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cmake</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 构建：编译出 hello.exe</span></span></code></pre></div><p>运行 <code>build\\Debug\\hello.exe</code>，打印 &quot;Hello CMake&quot;。</p></details></li><li><p>Cmake 如何在构建时自动拉取 C++ 第三方库（如 glm）？</p><details class="details custom-block"><summary>查看答案</summary><p>用 CMake 自带的 <strong>FetchContent</strong>，自动拉取发生在<strong>配置阶段</strong>（<code>cmake -B build</code> 时），不是编译阶段。CMakeLists.txt 里三步：</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(FetchContent)                           </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 引入模块</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FetchContent_Declare(glm                        </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 声明：仓库 + 锁定版本</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  GIT_REPOSITORY https://github.com/g-truc/glm</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  GIT_TAG 1.0.3)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FetchContent_MakeAvailable(glm)                 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 下载并纳入构建</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_link_libraries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(glm-cpp </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PRIVATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> glm::glm) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 链接</span></span></code></pre></div><p>配置时 git clone 源码到 build 缓存（之后离线可重复构建），和你的工程一起编译——纯头文件库（glm）零编译成本，下载完直接 include 即用。</p></details></li><li><p>改了 CMakeLists.txt 需要重新配置吗？</p><details class="details custom-block"><summary>查看答案</summary><p>需要重新<strong>配置</strong>，但通常不用手动做：<code>cmake --build build</code> 构建前会检测 CMakeLists.txt 的时间戳，变了就自动先重新配置再编译；VS 打开文件夹时保存 CMakeLists.txt 也会立即自动重新配置。</p><p>日常流程：</p><ul><li>只改代码 → 直接 <code>cmake --build build</code>（增量编译，只编改过的文件）</li><li>改 CMakeLists.txt / CMakePresets.json → 直接 build 也行（自动补配置）；显式 <code>cmake -B build</code> 更保险、日志看得清</li><li>换工具链 / 配置缓存异常 → 删 build 目录重新 <code>cmake -B build</code></li></ul><p>一句话：配置一次、构建多次；改了 CMakeLists 忘了重跑配置没关系，build 会替你补上。</p></details></li></ol>`,5)])])}const g=a(l,[["render",t]]);export{r as __pageData,g as default};
